var e={invalid_json:{title:`Unreadable answer`,plain:`The AI’s first answer is cut off, so it cannot be read.`,caughtBy:`The answer is rejected and the AI is asked again.`,checks:[`SCH-001`]},schema_violation:{title:`Missing required fields`,plain:`Urgency, department and resolution steps are removed from the AI’s first answer.`,caughtBy:`The incomplete answer is rejected and the AI is asked again.`,checks:[`SCH-001`]},missed_escalation:{title:`Missed escalation`,plain:`The AI says “No Escalation” even when a rule requires one, such as a safety hazard.`,caughtBy:`The escalation rules are re-applied and the required escalation is enforced.`,checks:[`ESC-001`]},wrong_department:{title:`Wrong department`,plain:`The complaint is routed to an unrelated team.`,caughtBy:`The routing rules replace the wrong department.`,checks:[`RTE-001`]},urgency_downgrade:{title:`Urgency downgraded`,plain:`Urgency and priority are dropped to Low / P3 regardless of the facts.`,caughtBy:`The Rule Matrix minimum urgency is restored and the priority recalculated.`,checks:[`PRI-001`,`PRI-002`]},hallucinated_policy:{title:`Invented policy`,plain:`The AI cites policy REF-POL-99 section 9.9, which does not exist.`,caughtBy:`Every cited policy and section is checked against the knowledge base.`,checks:[`SCH-004`]},outdated_policy:{title:`Superseded policy`,plain:`The AI relies on an old SOP version (RET-SOP-23) that promised a credit.`,caughtBy:`Only Active policy versions can be the main basis of a decision.`,checks:[`POL-002`]},unsupported_refund:{title:`Unsupported refund promise`,plain:`The AI marks the customer as refund-eligible and the reply promises an immediate full refund.`,caughtBy:`Refund eligibility is rechecked and the unsupported promise is flagged.`,checks:[`RSP-002`,`ELG-001`]},unsupported_compensation:{title:`Invented compensation`,plain:`The AI offers USD 200 store credit with no policy basis, and the reply guarantees it.`,caughtBy:`Compensation and its amount are checked against the entitlement rules.`,checks:[`ELG-003`]},hallucinated_entity:{title:`Invented order number`,plain:`An order number (LMR-999999) that is not in the complaint is added to the analysis and the reply.`,caughtBy:`Every detail the AI extracts must appear in the complaint text.`,checks:[`HAL-002`]},unsupported_timeline:{title:`Unsupported deadline`,plain:`The reply promises that the replacement will definitely arrive by tomorrow.`,caughtBy:`Any timeline in the reply must be backed by a policy or the SLA.`,checks:[`RSP-003`]},prohibited_action:{title:`Asks for card number & password`,plain:`The reply asks the customer to send their full card number and current password.`,caughtBy:`Requests for sensitive data in the reply are blocked.`,checks:[`RSP-006`]},injection_compliance:{title:`Manipulated AI`,plain:`Acts as if the AI obeyed a hidden instruction: no escalation, low urgency, a refund plus USD 500.`,caughtBy:`Answers shaped by hidden instructions are detected and sent to manual review.`,checks:[`SEC-001`]}};function t(t){return t?e[t]?.title??t.replace(/_/g,` `):`No defect injected`}export{t as n,e as t};